# Jordan normal form, after _jordan_form and _jordan_form_rational_matrix in
# sympy/matrices/eigen.py. Rational matrices are handled as SymPy does, in
# the algebraic field generated by one root of each factor of the
# characteristic polynomial, with DomainMatrix's fraction-free nullspace
# (sdm_rref_den), so the transform matches SymPy's columns.

# ---------------------------------------------------------------------------
# QQ<a> = QQ[t]/(m(t)): elements are bigq coefficient vectors, low degree first

.af_new <- function(m) {
  m <- m / m[length(m)]                  # monic, low degree first
  d <- length(m) - 1L
  zero <- gmp::as.bigq(rep(0, d))
  red <- function(p) {                    # p low degree first
    p <- gmp::as.bigq(p)
    while (length(p) > d) {
      k <- length(p); c <- p[k]
      if (c != 0) { idx <- (k - d):(k - 1L); p[idx] <- p[idx] - c * m[1:d] }
      p <- p[-k]
    }
    if (length(p) < d) p <- c(p, gmp::as.bigq(rep(0, d - length(p))))
    p
  }
  mul <- function(a, b) {
    r <- gmp::as.bigq(rep(0, 2L * d - 1L))
    for (i in seq_len(d)) if (a[i] != 0) for (j in seq_len(d)) if (b[j] != 0) r[i + j - 1L] <- r[i + j - 1L] + a[i] * b[j]
    red(r)
  }
  is_zero <- function(a) all(a == 0)
  inv <- function(a) {
    # solve a*y = 1 by the multiplication matrix
    Mt <- lapply(seq_len(d), function(j) { e <- zero; e[j] <- 1; mul(a, e) })
    A <- lapply(seq_len(d), function(i) c(lapply(seq_len(d), function(j) Mt[[j]][i]), list(gmp::as.bigq(if (i == 1L) 1 else 0))))
    for (cl in seq_len(d)) {
      p <- which(vapply(cl:d, function(i) A[[i]][[cl]] != 0, TRUE))[1L] + cl - 1L
      tmp <- A[[cl]]; A[[cl]] <- A[[p]]; A[[p]] <- tmp
      pv <- A[[cl]][[cl]]; A[[cl]] <- lapply(A[[cl]], function(z) z / pv)
      for (i in seq_len(d)) if (i != cl && A[[i]][[cl]] != 0) {
        f <- A[[i]][[cl]]; A[[i]] <- Map(function(z, w) z - f * w, A[[i]], A[[cl]])
      }
    }
    do.call(base::c, lapply(seq_len(d), function(i) A[[i]][[d + 1L]]))
  }
  list(d = d, m = m, zero = zero,
       one = { e <- zero; e[1] <- 1; e },
       gen = if (d == 1L) gmp::as.bigq(-m[1]) else { e <- zero; e[2] <- 1; e },
       const = function(q) { e <- zero; e[1] <- gmp::as.bigq(q); e },
       add = function(a, b) a + b, sub = function(a, b) a - b, neg = function(a) -a,
       mul = mul, is_zero = is_zero,
       exquo = function(a, b) mul(a, inv(b)),
       is_one = function(a) a[1] == 1 && all(a[-1] == 0),
       is_negative = function(a) { nz <- which(a != 0); length(nz) > 0L && a[max(nz)] < 0 })
}

# sdm_rref_den over the field K; rows are lists of elements, zero = absent
.af_rref_den <- function(rows, K, n) {
  nz <- function(r) which(!vapply(r, K$is_zero, TRUE))
  rows <- Filter(function(r) length(nz(r)) > 0L, rows)
  if (!length(rows)) return(list(rows = list(), den = K$one, pivots = integer()))
  if (length(rows) == 1L) { j <- min(nz(rows[[1L]])); return(list(rows = rows, den = rows[[1L]][[j]], pivots = j)) }
  rows <- rows[order(vapply(rows, function(r) min(nz(r)), 0L))]
  reduced <- list(); unreduced <- list()   # names: column, value: row index
  out <- list(); denom <- NULL; divisor <- NULL
  scale <- function(r, f) lapply(r, function(z) if (K$is_zero(z)) z else K$mul(z, f))
  divide <- function(r) if (is.null(divisor)) r else lapply(r, function(z) if (K$is_zero(z)) z else K$exquo(z, divisor))
  for (Ai in rows) {
    for (cc in names(reduced)) Ai[[as.integer(cc)]] <- K$zero
    cancel <- rep(list(K$zero), n)
    for (cc in names(unreduced)) {
      j <- as.integer(cc)
      if (K$is_zero(Ai[[j]])) next
      Aij <- Ai[[j]]; Ai[[j]] <- K$zero
      Aj <- out[[unreduced[[cc]]]]
      for (k in nz(Aj)) cancel[[k]] <- K$add(cancel[[k]], K$mul(Aij, Aj[[k]]))
    }
    d <- if (is.null(denom)) K$one else denom
    Ai <- Map(function(a, c) K$sub(K$mul(a, d), c), Ai, cancel)
    if (!length(nz(Ai))) next
    j <- min(nz(Ai)); Aij <- Ai[[j]]; Ai[[j]] <- K$zero
    for (cc in names(unreduced)) {
      k <- unreduced[[cc]]; Ak <- out[[k]]
      if (K$is_zero(Ak[[j]])) { out[[k]] <- divide(scale(Ak, Aij)); next }
      Akj <- Ak[[j]]; Ak[[j]] <- K$zero
      Ak <- divide(Map(function(a, b) K$sub(K$mul(Aij, a), K$mul(Akj, b)), Ak, Ai))
      out[[k]] <- Ak
      if (!length(nz(Ak))) { unreduced[[cc]] <- NULL; reduced[[cc]] <- k }
    }
    i <- length(out) + 1L
    out[[i]] <- Ai
    if (length(nz(Ai))) unreduced[[as.character(j)]] <- i else reduced[[as.character(j)]] <- i
    if (!K$is_one(Aij)) denom <- if (is.null(denom)) Aij else K$mul(denom, Aij)
    if (!is.null(divisor)) denom <- K$exquo(denom, divisor)
    divisor <- denom
  }
  if (is.null(denom)) denom <- K$one
  c2r <- c(reduced, unreduced)
  piv <- as.integer(names(c2r)); ridx <- unlist(c2r)
  o <- order(piv)
  pivots <- piv[o]; rr <- out[ridx[o]]
  for (i in seq_along(rr)) rr[[i]][[pivots[i]]] <- denom
  list(rows = rr, den = denom, pivots = pivots)
}

# DomainMatrix.nullspace: rref_den, sign of den made canonical, then
# nullspace_from_rref (each vector carries the pivot value)
.af_nullspace <- function(rows, K, n) {
  r <- .af_rref_den(rows, K, n)
  if (K$is_negative(r$den)) r$rows <- lapply(r$rows, function(rw) lapply(rw, K$neg))
  if (!length(r$pivots)) return(lapply(seq_len(n), function(j) { v <- rep(list(K$zero), n); v[[j]] <- K$one; v }))
  if (length(r$pivots) == n) return(list())
  pv <- r$rows[[1L]][[r$pivots[1L]]]
  lapply(setdiff(seq_len(n), r$pivots), function(j) {
    v <- rep(list(K$zero), n); v[[j]] <- pv
    for (i in seq_along(r$rows)) if (!K$is_zero(r$rows[[i]][[j]])) v[[r$pivots[i]]] <- K$neg(r$rows[[i]][[j]])
    v
  })
}
.af_matmul <- function(A, B, K, n) lapply(seq_len(n), function(i) lapply(seq_len(n), function(j) {
  s <- K$zero
  for (k in seq_len(n)) if (!K$is_zero(A[[i]][[k]]) && !K$is_zero(B[[k]][[j]])) s <- K$add(s, K$mul(A[[i]][[k]], B[[k]][[j]]))
  s
}))
.af_matvec <- function(A, v, K, n) lapply(seq_len(n), function(i) {
  s <- K$zero
  for (k in seq_len(n)) if (!K$is_zero(A[[i]][[k]]) && !K$is_zero(v[[k]])) s <- K$add(s, K$mul(A[[i]][[k]], v[[k]]))
  s
})
.af_rank <- function(rows, K, n) length(.af_rref_den(rows, K, n)$pivots)
# an element as an expression in the root val (c0 + c1*val + ...)
.af_expr <- function(a, val) .add(lapply(seq_along(a), function(k)
  if (a[k] == 0) S_Zero else .mul(list(make_rational(a[k]), if (k == 1L) S_One else .pow(val, .int(k - 1L))))))

# _blocks_from_nullity_chain
.blocks_from_nullity <- function(d) {
  n <- length(d)
  mid <- if (n > 2L) vapply(2:(n - 1L), function(k) 2L * d[k] - d[k - 1L] - d[k + 1L], 0L) else integer()
  c(mid, if (n > 1L) d[n] - d[n - 1L] else d[1L])
}

# SymPy's roots_quadratic order for an irreducible a*x^2 + b*x + c
.quad_roots <- function(cf) {
  a <- make_rational(cf[[1L]]); b <- make_rational(cf[[2L]]); c <- make_rational(cf[[3L]])
  if (is_zero_num(b)) { R <- sqrt(.neg(.div(c, a))); r <- list(.neg(R), R) }
  else {
    A <- .mul(list(S_Two, a)); B <- .div(.neg(b), A)
    D <- factor_terms(.div(sqrt(.sub(.pow(b, S_Two), .mul(list(.int(4L), a, c)))), A))
    r <- list(.sub(B, D), .add(list(B, D)))
  }
  if (num_sign(a) < 0) r <- rev(r)
  r
}

.jordan_rational <- function(M, calc_transform) {
  n <- M$nrow
  l <- Dummy("lambda")
  cp <- charpoly(M, l)
  fl <- factor_list(cp, l)$factors
  facs <- lapply(fl, function(p) {
    cl <- lapply(.coeff_list(p[[1L]], l), function(z) gmp::as.bigq(z$value))
    den <- Reduce(gmp::lcm.bigz, lapply(cl, gmp::denominator), gmp::as.bigz(1))
    ci <- lapply(cl, function(q) gmp::as.bigz(q * den))
    g <- Reduce(gmp::gcd.bigz, lapply(ci, abs))
    ci <- lapply(ci, function(z) z / g)
    if (ci[[1L]] < 0) ci <- lapply(ci, function(z) -z)
    list(coeffs = ci, mult = as.integer(p[[2L]]))
  })
  # _sort_factors: by length, multiplicity, then the coefficients
  ord <- seq_along(facs)
  if (length(facs) > 1L) {
    cmp <- function(x, y) {
      if (length(x$coeffs) != length(y$coeffs)) return(sign(length(x$coeffs) - length(y$coeffs)))
      if (x$mult != y$mult) return(sign(x$mult - y$mult))
      for (k in seq_along(x$coeffs)) if (x$coeffs[[k]] != y$coeffs[[k]]) return(if (x$coeffs[[k]] < y$coeffs[[k]]) -1 else 1)
      0
    }
    ord <- integer()
    for (i in seq_along(facs)) { j <- length(ord); while (j > 0L && cmp(facs[[ord[j]]], facs[[i]]) > 0) j <- j - 1L; ord <- append(ord, i, after = j) }
  }
  facs <- facs[ord]
  for (k in seq_along(facs)) {
    cf <- facs[[k]]$coeffs
    facs[[k]]$eigs <- if (length(cf) == 2L) list(make_rational(gmp::as.bigq(-cf[[2L]], cf[[1L]])))
      else if (length(cf) == 3L) .quad_roots(cf)
      else {
        # Poly.all_roots: an irreducible factor of degree 3 or more gives CRootOf
        pe <- .add(lapply(seq_along(cf), function(t) .mul(list(.int(cf[[t]]), .pow(l, .int(length(cf) - t))))))
        lapply(seq_len(length(cf) - 1L) - 1L, function(t) CRootOf(pe, l, t))
      }
    facs[[k]]$K <- .af_new(rev(gmp::as.bigq(do.call(base::c, cf))))
  }
  # the characteristic matrix M - a*I over QQ<a>
  char_mat <- function(K) lapply(seq_len(n), function(i) lapply(seq_len(n), function(j) {
    e <- K$const(.mget(M, i, j)$value)
    if (i == j) K$sub(e, K$gen) else e
  }))
  nullcache <- list()
  sizes <- list(); jblocks <- list()
  for (k in seq_along(facs)) {
    f <- facs[[k]]; K <- f$K
    if (f$mult == 1L) bs <- 1L
    else {
      C <- char_mat(K); P <- C
      vecs <- .af_nullspace(P, K, n); nul <- length(vecs)
      if (f$mult == nul) nullcache[[as.character(k)]] <- vecs
      ret <- 0L
      while (nul != ret[length(ret)]) {
        ret <- c(ret, nul)
        if (nul == f$mult) break
        P <- .af_matmul(P, C, K, n)
        nul <- length(.af_nullspace(P, K, n))
      }
      bs <- .blocks_from_nullity(ret)
    }
    sz <- integer()
    for (s in rev(seq_along(bs))) sz <- c(sz, rep(s, bs[s]))
    facs[[k]]$sizes <- sz
    for (r in f$eigs) for (s in sz) jblocks[[length(jblocks) + 1L]] <- list(r, s)
  }
  J <- zeros(n, n); pos <- 0L
  for (b in jblocks) {
    for (t in seq_len(b[[2L]])) {
      J$data[[(pos + t - 1L) * n + pos + t]] <- b[[1L]]
      if (t < b[[2L]]) J$data[[(pos + t - 1L) * n + pos + t + 1L]] <- S_One
    }
    pos <- pos + b[[2L]]
  }
  if (!calc_transform) return(J)
  basis <- list()
  tovec <- function(v, val) lapply(v, function(a) .af_expr(a, val))
  for (k in seq_along(facs)) {
    f <- facs[[k]]; K <- f$K
    if (!is.null(nullcache[[as.character(k)]]) || f$mult == 1L) {
      vects <- if (!is.null(nullcache[[as.character(k)]])) nullcache[[as.character(k)]] else .af_nullspace(char_mat(K), K, n)
      for (val in f$eigs) for (v in vects) basis[[length(basis) + 1L]] <- tovec(v, val)
    } else {
      C <- char_mat(K)
      cpow <- function(s) {
        if (s == 0L) return(lapply(seq_len(n), function(i) lapply(seq_len(n), function(j) if (i == j) K$one else K$zero)))
        P <- C; for (t in seq_len(s - 1L)) P <- .af_matmul(P, C, K, n); P
      }
      eig_basis <- list(); gen <- list()
      for (idx in seq_along(f$sizes)) {
        s <- f$sizes[idx]
        big <- .af_nullspace(cpow(s), K, n); small <- .af_nullspace(cpow(s - 1L), K, n)
        vec <- NULL
        if (!length(eig_basis) && !length(small)) vec <- big[[1L]]
        else for (v in big) {
          cols <- c(small, eig_basis, list(v))
          rows <- lapply(seq_len(n), function(i) lapply(cols, function(cl) cl[[i]]))
          pv <- .af_rref_den(rows, K, length(cols))$pivots
          if (length(pv) && pv[length(pv)] == length(cols)) { vec <- v; break }
        }
        nv <- list(vec); P <- C
        if (s > 1L) nv[[2L]] <- .af_matvec(P, vec, K, n)
        if (s > 2L) for (t in 3:s) { P <- .af_matmul(P, C, K, n); nv[[t]] <- .af_matvec(P, vec, K, n) }
        eig_basis <- c(eig_basis, nv)
        gen[[idx]] <- nv
      }
      for (val in f$eigs) for (idx in seq_along(f$sizes))
        for (v in rev(gen[[idx]])) basis[[length(basis) + 1L]] <- tovec(v, val)
    }
  }
  P <- .new_mat(unlist(lapply(seq_len(n), function(i) lapply(basis, function(v) v[[i]])), recursive = FALSE), n, length(basis))
  list(P = P, J = J)
}

# _jordan_form for matrices with symbolic entries
.jordan_symbolic <- function(M, calc_transform) {
  n <- M$nrow
  ev <- eigenvals(M)
  mult <- attr(ev, "multiplicity")
  if (any(vapply(ev, function(v) .has_type(v, "CRootOf"), TRUE)))
    stop("Jordan normal form is not implemented if the matrix have eigenvalues in CRootOf form")
  o <- if (length(ev) > 1L) { ks <- lapply(ev, .sort_key); oo <- .key_sort(ks, seq_along(ev)); unlist(oo) } else seq_along(ev)
  ev <- ev[o]; mult <- mult[o]
  cache <- list()
  eig_mat <- function(k, p) {
    key <- paste(k, p)
    if (is.null(cache[[key]])) {
      A <- M - .mat_map(eye(n), function(z) .mul(list(z, ev[[k]])))
      R <- A
      if (p > 1L) for (t in 2:p) R <- R %*% A
      cache[[key]] <<- .mat_map(R, expand)
    }
    cache[[key]]
  }
  if (length(ev) == n) {
    J <- diag_matrix(ev)
    if (!calc_transform) return(J)
    cols <- lapply(seq_along(ev), function(k) nullspace(eig_mat(k, 1L))[[1L]])
    P <- .new_mat(unlist(lapply(seq_len(n), function(i) lapply(cols, function(cl) cl$data[[i]])), recursive = FALSE), n, n)
    return(list(P = P, J = J))
  }
  structure <- list()
  for (k in seq_along(ev)) {
    am <- mult[k]
    ret <- 0L; nul <- n - rank_matrix(eig_mat(k, 1L)); p <- 2L
    while (nul != ret[length(ret)]) {
      ret <- c(ret, nul)
      if (nul == am) break
      nul <- n - rank_matrix(eig_mat(k, p)); p <- p + 1L
      if (nul < ret[length(ret)] || nul > am) stop("SymPy had encountered an inconsistent result while computing Jordan block")
    }
    bs <- .blocks_from_nullity(ret)
    for (s in rev(seq_along(bs))) for (t in seq_len(bs[s])) structure[[length(structure) + 1L]] <- list(k, s)
  }
  if (sum(vapply(structure, `[[`, 0L, 2L)) != n) stop("SymPy had encountered an inconsistent result while computing Jordan block")
  J <- zeros(n, n); pos <- 0L
  for (b in structure) {
    for (t in seq_len(b[[2L]])) {
      J$data[[(pos + t - 1L) * n + pos + t]] <- ev[[b[[1L]]]]
      if (t < b[[2L]]) J$data[[(pos + t - 1L) * n + pos + t + 1L]] <- S_One
    }
    pos <- pos + b[[2L]]
  }
  if (!calc_transform) return(J)
  basis <- list()
  for (k in seq_along(ev)) {
    eig_basis <- list()
    for (b in structure) {
      if (b[[1L]] != k) next
      s <- b[[2L]]
      big <- nullspace(eig_mat(k, s))
      small <- if (s > 1L) nullspace(eig_mat(k, s - 1L)) else list()
      prev <- c(small, eig_basis)
      vec <- if (!length(prev)) big[[1L]] else {
        found <- NULL
        for (v in big) {
          cols <- c(prev, list(v))
          H <- .new_mat(unlist(lapply(seq_len(n), function(i) lapply(cols, function(cl) cl$data[[i]])), recursive = FALSE), n, length(cols))
          pv <- .rref(H)$pivots
          if (length(pv) && pv[length(pv)] == length(cols)) { found <- v; break }
        }
        found
      }
      nv <- lapply(seq_len(s) - 1L, function(t) if (t == 0L) vec else .mat_map(eig_mat(k, t) %*% vec, expand))
      eig_basis <- c(eig_basis, nv)
      basis <- c(basis, rev(nv))
    }
  }
  P <- .new_mat(unlist(lapply(seq_len(n), function(i) lapply(basis, function(cl) cl$data[[i]])), recursive = FALSE), n, n)
  list(P = P, J = J)
}

#' Jordan normal form
#'
#' `jordan_form(M)` returns `list(P, J)` with `M = P J P^-1` and `J` in Jordan
#' normal form, as SymPy's `Matrix.jordan_form()`; with `calc_transform =
#' FALSE` only `J`. Rational matrices are worked in the algebraic field of
#' each factor of the characteristic polynomial, as SymPy does, so the
#' columns of `P` agree with SymPy's.
#'
#' @param M A square `symmatrix`.
#' @param calc_transform Also compute the transform `P`.
#' @return `list(P = , J = )`, or the matrix `J`.
#' @examples
#' jordan_form(Matrix(list(list(1, 1, 0), list(0, 1, 0), list(0, 0, 2))))
#' @export
jordan_form <- function(M, calc_transform = TRUE) {
  M <- Matrix(M)
  if (M$nrow != M$ncol) stop("Only square matrices have Jordan forms")
  floats <- any(vapply(M$data, function(z) .has_type(z, "Float"), TRUE))
  dps <- 15L
  if (floats) {
    M <- .mat_map(M, function(z) nsimplify(z, rational = TRUE))
  }
  restore <- function(X) if (floats) .mat_map(X, function(z) N(z, dps)) else X
  rational <- all(vapply(M$data, function(z) z$type %in% c("Integer", "Rational"), TRUE))
  r <- if (rational) .jordan_rational(M, calc_transform) else .jordan_symbolic(M, calc_transform)
  if (!calc_transform) return(restore(r))
  list(P = restore(r$P), J = restore(r$J))
}
